mapper.select:
/* selectMasterMdCdBuyerCardManageList */ SELECT X.BUYER, X.COM_NAME_LOC, X.PRE_VISIT, X.THAT_VISIT, (SELECT B.TEXT1 FROM ICOMCOD2 B WHERE B.COMPANY_CODE ='KRKORE0001' AND B.TYPE ='C001' AND B.FLAG = 'Y' AND B.CODE = X.USR_DEPT) AS USR_DEPT_NM, TO_CHAR(TO_DATE(X.LST_VISIT_DATE, 'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI') AS LST_VISIT_DATE, X.USR_ID, X.USR_DEPT, X.USR_RSPNSR FROM ( SELECT VI.BUYER, GETCMSLOCNAME(VI.BUYER, VI.SITE) AS COM_NAME_LOC, (SELECT DECODE(COUNT(BUYER),0,'N','Y') FROM KEP_VISITDT DT WHERE DT.BUYER = VI.BUYER AND SUBSTR(DT.VISIT_DATE,0,6) = TO_CHAR(ADD_MONTHS(SYSDATE,-1), 'YYYYMM') AND DT.STATUS <> 'D') AS PRE_VISIT, (SELECT DECODE(COUNT(BUYER),0,'N','Y') FROM KEP_VISITDT DT WHERE DT.BUYER = VI.BUYER AND SUBSTR(DT.VISIT_DATE,0,6) = TO_CHAR(SYSDATE, 'YYYYMM') AND DT.STATUS <> 'D') AS THAT_VISIT, (SELECT MAX(DT.VISIT_DATE||DT.VISIT_TIME) FROM KEP_VISITDT DT WHERE DT.BUYER = VI.BUYER AND STATUS <> 'D') AS LST_VISIT_DATE, (SELECT MAX(ADD_USER_ID) FROM KEP_VISITDT A WHERE A.BUYER = VI.BUYER AND A.STATUS <> 'D' AND A.VISIT_DATE||A.VISIT_TIME||A.ADD_USER_ID = (SELECT MAX(DT.VISIT_DATE||DT.VISIT_TIME||DT.ADD_USER_ID) FROM KEP_VISITDT DT WHERE DT.BUYER = A.BUYER AND STATUS <> 'D')) AS USR_ID, GETCMSRSPNSR(VI.BUYER,'BM','DEPT') AS USR_DEPT, GETCMSRSPNSR(VI.BUYER,'BM','USR_NM') AS USR_RSPNSR, #{st_user_dept} AS DEPT_A FROM KEP_VISITHD VI WHERE VI.STATUS <> 'D' AND NVL(VI.POTENTIAL_CUSTOMER_YN,'N') = 'N'
AND VI.BUYER = #{st_buyer_code}
) X WHERE 1=1
AND (X.USR_DEPT = #{st_user_dept} OR X.BUYER =DECODE(X.DEPT_A, '048', '', '') )
AND ( X.USR_ID = #{st_kep_user_id} OR EXISTS (SELECT 1 FROM KEP_VISITDT DT WHERE DT.ADD_USER_ID = #{st_kep_user_id} AND DT.STATUS <> 'D' AND X.BUYER = DT.BUYER) )
AND X.PRE_VISIT = #{st_avisit_gbn}
AND X.THAT_VISIT = #{st_bvisit_gbn}
ORDER BY X.COM_NAME_LOC

/* selectMasterMdCdBuyerCardManageVisitorList */ SELECT L.USER_ID AS CODE, L.USER_NAME_LOC AS TEXT1 FROM ICOMLUSR L WHERE L.COM_CODE = 'KRKORE0001' AND L.STATUS <> 'D' AND L.DEPARTMENT IN ('001','008','009','012','017','042','043','048','010') AND (L.OFFICE_YN IS NULL OR L.OFFICE_YN <> 'Y' )
AND L.DEPARTMENT = #{SEARCH1}
ORDER BY L.USER_NAME_LOC
